import test from 'node:test';
import assert from 'node:assert/strict';
import { normalize } from '../src/normalize.js';

test('trims surrounding whitespace and lowercases letters', () => {
  assert.equal(normalize('  HeLLo  '), 'hello');
  assert.equal(normalize('\t\nMiXeD\r\n'), 'mixed');
  assert.equal(normalize('A'), 'a');
  assert.equal(normalize('  hello'), 'hello');
  assert.equal(normalize('hello  '), 'hello');
});

test('preserves internal whitespace while lowercasing', () => {
  assert.equal(normalize(' A  B\tC\nD '), 'a  b\tc\nd');
  assert.equal(normalize('X\r\nY'), 'x\r\ny');
});

test('returns empty for empty and all-whitespace strings', () => {
  assert.equal(normalize(''), '');
  assert.equal(normalize(' '), '');
  assert.equal(normalize('   '), '');
  assert.equal(normalize('\t\n\r\n'), '');
  assert.equal(normalize(' \t\r\n '), '');
});

test('leaves already normalized text unchanged', () => {
  assert.equal(normalize('hello'), 'hello');
  assert.equal(normalize('a  b\tc\nd'), 'a  b\tc\nd');
  assert.equal(normalize('hello, world! 123'), 'hello, world! 123');
});

const nonStrings = [
  ['undefined', undefined],
  ['null', null],
  ['false', false],
  ['true', true],
  ['zero', 0],
  ['negative number', -1],
  ['fraction', 1.5],
  ['NaN', NaN],
  ['Infinity', Infinity],
  ['bigint', 1n],
  ['symbol', Symbol('text')],
  ['empty array', []],
  ['string array', ['hello']],
  ['object', {}],
  ['string-like object', { toString: () => 'hello' }],
  ['function', () => 'hello'],
  ['boxed string', new String('hello')],
];

for (const [label, value] of nonStrings) {
  test(`throws TypeError for ${label}`, () => {
    assert.throws(() => normalize(value), TypeError);
  });
}

test('throws TypeError when called without an argument', () => {
  assert.throws(() => normalize(), TypeError);
});

